package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	line := scanner.Text()
	parts := strings.Fields(line)

	L, _ := strconv.Atoi(parts[0])
	R, _ := strconv.Atoi(parts[1])
	C, _ := strconv.Atoi(parts[2])

	diff := abs(L - R)

	if diff >= C {
		minLR := min(L, R)
		maxLR := max(L, R)
		result := min(maxLR, minLR+C) * 2
		fmt.Println(result)
	} else {
		if L > R {
			R += diff
		} else {
			L += diff
		}
		C -= diff
		result := (C/2 + L) * 2
		fmt.Println(result)
	}
}

